INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier\'s system sends repair data to finance each night as a fixed-width text file, shortens long descriptions to 80 characters, and keeps the only copy of old records on a server that is 12 years old. Explain where these design habits come from and what you would ask for.', 'The fixed-width file, the 80-character limit and the overnight batch run all come from the punched-card and mainframe era, when data was a list of identical records with each field in a set position and processing happened in one run. They are not wrong in themselves, but they limit the service: long descriptions are cut off, finance sees yesterday\'s data, and adding a new field means changing a rigid format. I would ask: why is it still batch, and can the integration move to an API or event so changes flow when they happen? What exactly is lost when descriptions are truncated, and can that be fixed? For the 12-year-old server holding the only copy of old records, I would ask about the risks of hardware failure and obsolete media or software: how many copies exist and where, are they on at least two kinds of media with one off-site (the 3-2-1 rule), when was a restore last tested, and in what format are the records kept so they stay readable for as long as the retention schedule says? I would link this to the council\'s records management plan, and ask for a migration plan with an exit route into open, documented formats so that the data does not depend on one machine, one supplier or one file format.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 2: How Code Actually Runs =====
