INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier proposes building a repairs tool in a language and style that nobody else at the council has used. Describe three questions you would ask about how it is built, and what each answer tells you about risk to the Repairs project.', 'Good questions: (1) Which language and framework is it written in, how widespread is the skill, and how easy is it to hire or contract people to support it? This reveals maintenance risk and dependence on the supplier. (2) How is it built, tested and released (is there an automated pipeline with test and UAT environments)? This shows whether changes can be made safely and repeatably, and whether a compiled build step or similar will affect the release process. (3) Is the code organised in a consistent, documented way, and can we see the documentation and code-review practice? This indicates how easy it will be for someone else to take over, and the likely quality. Also worth asking: is the code ours to keep if the contract ends, and can it be run elsewhere? Clear, confident answers point to a professional team; vague answers about "proprietary magic" or reliance on one or two named individuals point to risk.', 0 FROM DUAL WHERE @mod > 0;

