INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'Three different suppliers are each building a separate part of the Repairs service: reporting, scheduling and payments. Explain, in plain English, why shared components, shared standards and accessibility testing matter, and what you would ask the project to put in place.', 'If each supplier builds its own address lookup, forms, login and error handling, tenants meet three different experiences, each part is tested and fixed separately, and any accessibility fault must be repaired three times. Shared components from a common design system give consistency, lower cost and a single place to fix problems. Shared standards (open APIs, common identifiers such as the property reference, agreed data definitions) mean the parts can exchange information without custom translation. Accessibility must be a requirement in each contract from the start, tested with real assistive technology and keyboard-only use, with a published statement against WCAG 2.2 AA. I would ask the project to put in place: a single shared design system and pattern library; agreed API and data standards written into procurement; an accessibility requirement and testing at every release; a shared list of common services (login, notifications, address lookup); and a lightweight governance group that approves exceptions. I would also ask each supplier how they use automated testing, linting and code review so quality is checked the same way everywhere.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 4: Shipping and Running Software =====
