INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'The supplier\'s system stores all of its repair priority and approval rules in database stored procedures that only one of their staff understands. Explain the risks to the Repairs project and what you would ask for.', 'The rules are the heart of the service, so having them hidden in database code known to one person is a serious risk. If that person leaves, nobody can safely change or even explain how decisions are made; the logic is hard to test, review or audit, and it may sit outside version control. It also ties the council to that specific database product, making it costly to change supplier. Performance can suffer as load grows because heavy logic in the database is hard to scale. I would ask for: the business rules to be documented in plain English and agreed with the service owners; a list of exactly what the stored procedures do; automated tests that prove the rules (for example that an emergency is escalated after four hours); the code held in version control with code review; a plan to move non-trivial rules into the application layer where they are visible; and a second named person who understands them. Simple integrity rules such as "a repair must have a property" can reasonably stay in the database. The aim is that the rules can be seen, tested, changed and handed over, not buried.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 6: When Things Go Wrong, and AI =====
