INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'Two weeks after launch, the Repairs service shows an occasional fault: some tenants are given an appointment slot that another tenant has also been given, and some contractors are paid twice for the same job. Nothing can be reproduced in testing. Explain what kinds of problem these are and what you would ask the supplier.', 'These are classic concurrency problems. The double-booked slots look like a race condition: two requests check availability at nearly the same time, both see a free slot, and both book it, because the check and the booking are not one atomic step. The double payments look like missing idempotency: a request that is retried after a timeout is processed twice. Because they only occur under real timing and retries, they cannot be reproduced when one tester works alone. Questions for the supplier: Is the booking done as a single atomic operation or inside a database transaction with locking or a unique constraint on the slot? Are payment and job-completion requests protected by idempotency keys so repeats are recognised? Is there version checking so that two updates to the same record cannot silently overwrite each other? Do they perform load and concurrency testing, with many users and repeated requests? What logging and monitoring exist to detect duplicates, and is there a regular reconciliation between completed jobs and payments, who investigates differences, and how are the duplicates already paid being recovered? I would also ask for an incident report that identifies the root cause and the fix, with a test that proves it will not recur.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 7: Keeping It Safe, Keeping It Open =====
