INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'Breaking the encryption mathematically' AS t, 0 AS c, 'Those are rare. The everyday route is through people and passwords.' AS e, 0 AS s
  UNION ALL SELECT 'Guessing the name of the server' AS t, 0 AS c, 'Those are rare. The everyday route is through people and passwords.' AS e, 1 AS s
  UNION ALL SELECT 'Tricking people, for example by phishing, and using weak or stolen passwords' AS t, 1 AS c, 'It is usually easier to deceive a person than to break a system.' AS e, 2 AS s
  UNION ALL SELECT 'Cutting the network cables' AS t, 0 AS c, 'Those are rare. The everyday route is through people and passwords.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'What makes a backup useful against ransomware?', 1 FROM DUAL WHERE @lesson > 0;
