INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'It is stored on the same server as the original' AS t, 0 AS c, 'A backup that the attacker can reach or that has never been tested may fail when needed.' AS e, 0 AS s
  UNION ALL SELECT 'It is never looked at' AS t, 0 AS c, 'A backup that the attacker can reach or that has never been tested may fail when needed.' AS e, 1 AS s
  UNION ALL SELECT 'It is made once a year' AS t, 0 AS c, 'A backup that the attacker can reach or that has never been tested may fail when needed.' AS e, 2 AS s
  UNION ALL SELECT 'At least one copy is offline or unchangeable, and restores have been tested' AS t, 1 AS c, 'Ransomware encrypts anything it can reach, so a protected copy and a proven restore are what save you.' AS e, 3 AS s) o WHERE @q > 0;
