SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'People and systems get only the access they need for their job' AS t, 1 AS c, 'Limiting access limits the damage a stolen account or a mistake can cause.' AS e, 0 AS s
  UNION ALL SELECT 'Everyone has full access so that work is not blocked' AS t, 0 AS c, 'That is the opposite of least privilege.' AS e, 1 AS s
  UNION ALL SELECT 'Only managers may use the system' AS t, 0 AS c, 'That is the opposite of least privilege.' AS e, 2 AS s
  UNION ALL SELECT 'Passwords must be as short as possible' AS t, 0 AS c, 'That is the opposite of least privilege.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Open source: how shared code runs the world', 'What open source is, how licences work, why it is everywhere in public services, and how to use it safely.', '## What open source means\n\n**Open source** software is software whose **source code**, the human-readable instructions written by developers, is published for anyone to read, use, change and share, under a **licence** that says what is allowed. "Open" here is about **freedom to see and adapt the code**, not about price. Open source software is often free to download, but running it still costs time, skills, hosting and support.\n\nYou already depend on it:\n\n- **Linux**, the operating system behind most servers, the cloud and Android.\n- **PHP, Python, JavaScript tools and many languages**, from the previous modules.\n- **MySQL and PostgreSQL**, databases you met earlier, and **WordPress**.\n- **Git**, **Docker** and **Kubernetes**.\n- The **web browsers** you use every day are built on open source engines.\n\n## Licences: the rules of the game\n\nThe licence is the legal heart of open source. Two broad families:\n\n- **Permissive licences** (such as **MIT** and **Apache 2.0**): do almost anything, including using it inside commercial or closed products, as long as you keep the credit notice.\n- **Copyleft licences** (such as the **GPL**): you may use and change it freely, but if you distribute a changed version you must share your changes under the same licence. The aim is to keep the code open for everyone.\n\n"Free" in this world has two meanings: **free as in speech** (freedom to use and change) and **free as in beer** (no price). Open source is mainly the first. Check the licence before building something important on top of it, because ignoring a licence can create legal problems.\n\n## Why public bodies like it\n\n- **No lock-in to one supplier.** If a product is open source, in principle anyone can support or take it over. This links directly to the lock-in questions from the first course.\n- **Transparency.** Public money, public scrutiny. Anyone can inspect how the software behaves.\n- **Reuse across the public sector.** Code written once for one council can be reused by another, and the UK government\'s **Service Standard** and **Technology Code of Practice** encourage public bodies to publish new source code openly and to use open source where it fits.\n- **Cost and flexibility.** There are no per-user licence fees, and the product can be adapted.\n- **Community.** Many people find and fix problems.\n\n## The risks and the myths\n\n- **Myth: "many eyes make it secure".** Open code *can* be reviewed by anyone, but in practice very few do. Serious flaws have hidden in popular projects for years. **Heartbleed** (2014), a flaw in a widely used encryption library, and **Log4Shell** (2021), in a very common logging tool, affected a huge part of the internet. In 2024 the **xz** compression tool was found to contain a deliberately planted back door, caught only by luck.\n- **Maintainers are often volunteers.** Critical software may be looked after by a handful of unpaid people. Using it without supporting it is a risk to everyone.\n- **"Free" is not free of cost.** You still need people who can install, secure, update and support it, or a supplier who will, under a contract with an SLA.\n- **Abandoned projects.** Look for signs of life: recent updates, many contributors, and a clear process for reporting security problems.\n- **The supply chain.** A project may include hundreds of other open source components. A **software bill of materials (SBOM)** is a list of everything inside a product, so you can check it when a new flaw is announced. Ask suppliers for one.\n\n## Open source and the Repairs project\n\nMany suppliers\' products are built on open source components, even if the product itself is proprietary. That is normal and healthy, but it means you should ask:\n\n- Which open source components and licences are inside this product, and can we see an SBOM?\n- How quickly do you apply security updates for those components?\n- If we choose an open source product, who provides **support**, and what happens if that supplier leaves?\n- Can our data be exported in an open, documented format, so that we are free to move?\n- Could we publish any of the work done for the Repairs project for other councils to reuse?\n\n::: try\nVisit **github.com** and open the page of an open source project you have met, for instance `php/php-src`, `torvalds/linux` or `WordPress/WordPress`. Find three things: the **licence** (look for a file called LICENSE), the date of the **latest update**, and how many **contributors** it has. Then do the same for a smaller, lesser-known project and compare: which would you be happier to depend on for a service that tenants rely on, and why?\n:::\n\n::: remember\nOpen source means you can **see, use and change** the code under a licence. It brings freedom and transparency, but it still needs skills, support and attention to security. "Free" does not mean "no cost" or "no risk".\n:::\n\n::: repairs\nA supplier proposes an open source repairs scheduling tool "because it is free". List four costs or risks that "free" leaves out, and four reasons it might nevertheless be the best choice for the Repairs project.\n:::', 3, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
