SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The software is always free to run with no costs' AS t, 0 AS c, 'Open source is licensed code, not free of all cost and not outside the law.' AS e, 0 AS s
  UNION ALL SELECT 'The source code is published under a licence that lets others read, use, change and share it' AS t, 1 AS c, 'Open refers to freedom to see and adapt the code. Running it may still cost money.' AS e, 1 AS s
  UNION ALL SELECT 'The software cannot be changed by anyone' AS t, 0 AS c, 'Open source is licensed code, not free of all cost and not outside the law.' AS e, 2 AS s
  UNION ALL SELECT 'The software is not protected by law' AS t, 0 AS c, 'Open source is licensed code, not free of all cost and not outside the law.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'Which statement about open source security is most accurate?', 1 FROM DUAL WHERE @lesson > 0;
