INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'It is always more secure than closed software' AS t, 0 AS c, 'Neither extreme is true. It depends on the care taken by the people maintaining the code and those using it.' AS e, 0 AS s
  UNION ALL SELECT 'It is always less secure than closed software' AS t, 0 AS c, 'Neither extreme is true. It depends on the care taken by the people maintaining the code and those using it.' AS e, 1 AS s
  UNION ALL SELECT 'The code can be inspected by anyone, but flaws have still hidden for years in popular projects' AS t, 1 AS c, 'Visibility allows review, but only if someone does the reviewing and maintains the code.' AS e, 2 AS s
  UNION ALL SELECT 'Security does not apply to open source' AS t, 0 AS c, 'Neither extreme is true. It depends on the care taken by the people maintaining the code and those using it.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier tells the project: "Our repairs platform is built on open source components, all data is encrypted, and we are Cyber Essentials certified." Explain what each claim does and does not tell you, and what you would ask next.', 'Built on open source components: this is normal and not a problem in itself, but it does not tell us which components, which licences, or how quickly security fixes are applied. I would ask for a software bill of materials, the licences involved, their patching policy and how they would react to a flaw such as Log4Shell. All data is encrypted: this is too vague to be reassuring. I would ask whether data is encrypted on the move, in storage (including backups) and who holds the keys, how keys are managed and rotated, what happens to keys and data if the contract ends, and whether they have a plan for post-quantum cryptography for long-lived data. Cyber Essentials certified: this shows a basic set of controls is in place, which is a useful minimum, but it is a baseline rather than a guarantee. I would ask about multi-factor authentication for all staff and admin accounts, least privilege, monitoring and logging, independent penetration testing, their incident response plan and notification times, how contractor and subcontractor access is controlled, how often backups are taken, whether one copy is offline or immutable, and when a restore was last tested. I would also ask for evidence rather than assurance, such as certificates, test summaries and a recent incident exercise, and write the answers into the contract with clear responsibilities and exit arrangements.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Glossary (existing terms are left untouched) =====
INSERT IGNORE INTO pm_learning_glossary (term, definition) VALUES
  ('punched card', 'A card with holes punched in set positions to record information. The standard IBM card had 80 columns and held 80 characters, and it shaped the fixed-width formats and batch processing still used today.'),
  ('batch processing', 'Collecting work together and processing it in one run, often overnight, rather than handling each item as it arrives.'),
  ('mainframe', 'A large, powerful central computer built for reliability and volume, used for decades by banks and government and descended from the machines that read punched cards.'),
  ('transistor', 'A tiny solid-state switch that replaced the valve. Billions of them on a chip make up a modern processor.'),
  ('integrated circuit', 'A chip: many transistors and their connections made together on one piece of silicon.'),
  ('Moore\'s law', 'The observation that the number of transistors on a chip roughly doubles every two years. It guided the industry for about fifty years and is now slowing.'),
  ('nanometre', 'One billionth of a metre. Chip features are now measured in nanometres, a few dozen atoms wide.'),
  ('RAM', 'Random Access Memory: the computer\'s fast working memory. It holds what you are using now and forgets everything when the power goes off.'),
  ('ROM', 'Read-Only Memory: memory that keeps its contents without power and holds the start-up instructions (firmware) a device runs first.'),
  ('firmware', 'Software stored in a device\'s permanent memory that starts it up and controls its hardware, such as the BIOS or UEFI on a PC.'),
  ('cache', 'A small, very fast store that keeps recently used data close to where it is needed so it can be fetched again quickly.'),
  ('SSD', 'Solid State Drive: storage made from flash memory with no moving parts, much faster than a spinning hard disk.'),
  ('byte', 'The unit of digital storage big enough for one character. A kilobyte is about a thousand bytes, a megabyte a million, a gigabyte a billion and a terabyte a trillion.'),
  ('qubit', 'The basic unit of a quantum computer. Unlike an ordinary bit, it can be in a blend of 0 and 1 until it is measured.'),
  ('quantum computing', 'Computing that uses quantum effects such as superposition and entanglement. It is expected to be good at a few specialist problems, not to speed up everyday software.'),
  ('post-quantum cryptography', 'New encryption methods designed to stay secure even against a large future quantum computer.'),
  ('symmetric encryption', 'Encryption where the same secret key locks and unlocks the data. Fast, and used for bulk data.'),
  ('public-key cryptography', 'Encryption using a pair of keys: a public one that anyone may have and a private one kept secret. It allows secure sharing and digital signatures.'),
  ('hash', 'A one-way fingerprint of data: a short fixed-length code that always comes out the same for the same input but cannot be reversed. Used to check integrity and store passwords.'),
  ('TLS', 'Transport Layer Security: the protocol that protects HTTPS connections, using public keys to agree a shared key and then encrypting the traffic.'),
  ('ransomware', 'Malicious software that locks an organisation\'s files by encrypting them and demands payment, often also stealing the data.'),
  ('defence in depth', 'Using several layers of protection so that if one fails another still stops the attack.'),
  ('zero trust', 'A security approach that does not assume anything is safe just because it is inside the network, and checks every request.'),
  ('open source', 'Software whose source code is published under a licence allowing anyone to read, use, change and share it.'),
  ('copyleft', 'A type of open source licence, such as the GPL, that requires changed versions to be shared under the same licence.'),
  ('software bill of materials', 'A list of every component and library inside a piece of software, so that it can be checked when a new flaw is announced. Often shortened to SBOM.'),
  ('compiler', 'A program that translates all of a program\'s source code into a ready-to-run file in one go, before it is run.'),
  ('interpreter', 'A program that reads source code and carries it out as it goes, line by line, without a separate translation step beforehand.'),
  ('DOM', 'Document Object Model: the tree of elements the browser builds from a page\'s HTML, which JavaScript can read and change to update what you see.'),
  ('object-oriented', 'A way of organising code around "objects" that bundle together information and the actions that can be done to it, such as a Repair that can be escalated or closed.'),
  ('functional programming', 'A way of organising code as small functions that take input and return output without changing anything else, chained together like machines on a line.'),
  ('framework', 'A ready-made structure for building a certain kind of software, such as React for web screens or Laravel for web back ends. It decides how your code is organised.'),
  ('library', 'A collection of ready-made code for one particular job, such as handling dates or drawing charts, which you call from your own code.'),
  ('CMS', 'Content Management System: software such as WordPress that lets non-developers create and edit a website\'s pages without writing code.'),
  ('React', 'A very widely used JavaScript library for building interactive screens out of reusable components.'),
  ('IDE', 'Integrated Development Environment: the editor developers write code in, with built-in help such as highlighting, auto-complete, debugging and testing.'),
  ('linting', 'Automatic checking of code for likely mistakes and style problems, a bit like a spell-checker for code.'),
  ('Prettier', 'A popular tool that automatically formats code in one consistent style, so nobody argues about spacing.'),
  ('Git', 'The standard version control system: it records every change to code as a labelled step that can be compared, shared and undone.'),
  ('GitHub', 'A website that hosts Git repositories and adds tools for teamwork such as pull requests, issues and code review.'),
  ('pull request', 'A proposal to merge changes from one branch into another, which a colleague reviews and approves before it joins the main version.'),
  ('code review', 'A colleague reading and checking proposed code changes for mistakes, security problems and clarity before they are accepted.'),
  ('DevOps', 'A way of working in which the people who build software and the people who run it work as one team, using automation to release changes quickly and safely.'),
  ('container', 'A lightweight, self-contained package holding an application and everything it needs to run, so it behaves the same wherever it is started.'),
  ('Docker', 'The best-known tool for building and running containers.'),
  ('Kubernetes', 'Software that runs and manages many containers across many servers, keeping the right number running and replacing any that fail.'),
  ('operating system', 'The core software of a device, such as Windows, macOS, Linux, iOS or Android, which manages the hardware and runs other programs.'),
  ('rendering engine', 'The part of a browser that turns code into the page you see. Chrome and Edge use Blink, Safari uses WebKit and Firefox uses Gecko.'),
  ('DBMS', 'Database Management System: the software that runs a database, stores the data safely and carries out requests to read or change it. MySQL, PostgreSQL, SQL Server, Oracle and MongoDB are examples.'),
  ('multi-model database', 'A database product that can handle more than one design at once, such as documents and graphs, in a single system. Cosmos DB and SurrealDB are examples.'),
  ('managed service', 'A product that a supplier runs for you, handling the servers, backups and updates, and charging for what you use. MongoDB Atlas is a managed service for MongoDB.'),
  ('document database', 'A database that stores each record as a flexible, self-describing document, usually JSON, rather than as a row in a fixed table.'),
  ('key-value store', 'A very simple, very fast database that stores each item under a unique name (the key) and looks it up by that name.'),
  ('graph database', 'A database designed around things and the relationships between them, which makes questions about connections quick to answer.'),
  ('time-series database', 'A database built for values recorded over time, such as sensor readings, and for questions about trends.'),
  ('Microsoft Graph', 'Microsoft\'s API for the data in Microsoft 365: people, mail, calendars, Teams, files and more, all connected.'),
  ('YAML', 'A human-friendly format for configuration, written as indented lines of name: value, widely used to describe how systems should be set up.'),
  ('concurrency', 'Several things happening at the same time, such as many users using one system at once.'),
  ('race condition', 'A bug where the result depends on which of two simultaneous actions happens to finish first. It can work perfectly in testing and fail rarely in real use.'),
  ('transaction', 'A group of database steps treated as a single unit: either all of them succeed together or none of them take effect.'),
  ('ACID', 'Four guarantees that make database transactions trustworthy: Atomicity (all or nothing), Consistency (rules always hold), Isolation (users do not interfere) and Durability (once saved, it stays saved).'),
  ('rollback', 'Undoing every step of an unfinished transaction so the data is exactly as it was before it started.'),
  ('locking', 'Reserving a piece of data so that only one user or process can change it at a time while others wait.'),
  ('idempotency key', 'A unique label sent with a request so that if the same request is sent twice by mistake, the system recognises it and does the action only once.'),
  ('ledger', 'An append-only record of every change, such as a bank\'s list of every debit and credit, where nothing is overwritten and the current balance is worked out from the entries.'),
  ('eventual consistency', 'A design in which different parts of a system may briefly disagree after a change but are guaranteed to agree shortly afterwards.'),
  ('stored procedure', 'Business logic saved and run inside the database itself, rather than in the application.'),
  ('large language model', 'A kind of AI trained on vast amounts of text to predict and generate language. ChatGPT and Claude are built on large language models.'),
  ('prompt', 'The instructions and context you give an AI tool, which strongly shape what it produces.'),
  ('hallucination', 'When an AI tool states something fluently and confidently that is false or invented.');
